public List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> result = new ArrayList<>();
    if (root == null) return result;
    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root);
    while (!queue.isEmpty()) {
        int size = queue.size();
        List<Integer> level = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            TreeNode node = queue.poll();
            level.add(node.val);
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        result.add(level);
    }
    return result;
}

public List<List<Integer>> zigzagLevelOrder(TreeNode root) {
    List<List<Integer>> result = new ArrayList<>();
    if (root == null) return result;
    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root);
    boolean leftToRight = true;
    while (!queue.isEmpty()) {
        int size = queue.size();
        LinkedList<Integer> level = new LinkedList<>();
        for (int i = 0; i < size; i++) {
            TreeNode node = queue.poll();
            if (leftToRight) level.addLast(node.val);
            else level.addFirst(node.val);
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        result.add(level);
        leftToRight = !leftToRight;
    }
    return result;
}

public List<Integer> rightSideView(TreeNode root) {
    List<Integer> result = new ArrayList<>();
    rightViewDFS(root, 0, result);
    return result;
}
private void rightViewDFS(TreeNode node, int depth, List<Integer> result) {
    if (node == null) return;
    if (depth == result.size()) {
        result.add(node.val);
    }
    rightViewDFS(node.right, depth + 1, result); // Go right first
    rightViewDFS(node.left, depth + 1, result);
}

public List<Integer> bottomView(TreeNode root) {
    List<Integer> result = new ArrayList<>();
    if (root == null) return result;
    Map<Integer, Integer> map = new TreeMap<>();
    Queue<TreeNode> queue = new LinkedList<>();
    root.val = 0; // Assuming we can store hd in node, else use a wrapper class
    queue.offer(root);
    while (!queue.isEmpty()) {
        TreeNode node = queue.poll();
        int hd = node.val;
        map.put(hd, node.val); // Overwrites, giving bottom view
        if (node.left != null) { node.left.val = hd - 1; queue.offer(node.left); }
        if (node.right != null) { node.right.val = hd + 1; queue.offer(node.right); }
    }
    for (int val : map.values()) result.add(val);
    return result;
}

public List<List<Integer>> verticalTraversal(TreeNode root) {
    TreeMap<Integer, TreeMap<Integer, PriorityQueue<Integer>>> map = new TreeMap<>();
    dfs(root, 0, 0, map);
    List<List<Integer>> result = new ArrayList<>();
    for (TreeMap<Integer, PriorityQueue<Integer>> ys : map.values()) {
        List<Integer> col = new ArrayList<>();
        for (PriorityQueue<Integer> nodes : ys.values()) {
            while (!nodes.isEmpty()) col.add(nodes.poll());
        }
        result.add(col);
    }
    return result;
}
private void dfs(TreeNode node, int x, int y, TreeMap<Integer, TreeMap<Integer, PriorityQueue<Integer>>> map) {
    if (node == null) return;
    map.putIfAbsent(x, new TreeMap<>());
    map.get(x).putIfAbsent(y, new PriorityQueue<>());
    map.get(x).get(y).offer(node.val);
    dfs(node.left, x - 1, y + 1, map);
    dfs(node.right, x + 1, y + 1, map);
}

public int widthOfBinaryTree(TreeNode root) {
    if (root == null) return 0;
    int maxWidth = 0;
    Queue<Pair<TreeNode, Integer>> queue = new LinkedList<>();
    queue.offer(new Pair<>(root, 0));
    while (!queue.isEmpty()) {
        int size = queue.size();
        int start = queue.peek().getValue();
        int end = start;
        for (int i = 0; i < size; i++) {
            Pair<TreeNode, Integer> curr = queue.poll();
            end = curr.getValue();
            if (curr.getKey().left != null) queue.offer(new Pair<>(curr.getKey().left, 2 * end));
            if (curr.getKey().right != null) queue.offer(new Pair<>(curr.getKey().right, 2 * end + 1));
        }
        maxWidth = Math.max(maxWidth, end - start + 1);
    }
    return maxWidth;
}

Map<TreeNode, TreeNode> parentMap = new HashMap<>();
public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
    buildParentMap(root, null);
    Queue<TreeNode> queue = new LinkedList<>();
    Set<TreeNode> visited = new HashSet<>();
    queue.offer(target);
    visited.add(target);
    int dist = 0;
    while (!queue.isEmpty()) {
        if (dist == k) break;
        int size = queue.size();
        for (int i = 0; i < size; i++) {
            TreeNode node = queue.poll();
            if (node.left != null && visited.add(node.left)) queue.offer(node.left);
            if (node.right != null && visited.add(node.right)) queue.offer(node.right);
            TreeNode parent = parentMap.get(node);
            if (parent != null && visited.add(parent)) queue.offer(parent);
        }
        dist++;
    }
    List<Integer> result = new ArrayList<>();
    while (!queue.isEmpty()) result.add(queue.poll().val);
    return result;
}
private void buildParentMap(TreeNode node, TreeNode parent) {
    if (node == null) return;
    parentMap.put(node, parent);
    buildParentMap(node.left, node);
    buildParentMap(node.right, node);
}

public TreeNode buildTree(int[] preorder, int[] inorder) {
    Map<Integer, Integer> inMap = new HashMap<>();
    for (int i = 0; i < inorder.length; i++) inMap.put(inorder[i], i);
    return build(preorder, 0, preorder.length - 1, 0, inorder.length - 1, inMap);
}
private TreeNode build(int[] pre, int preStart, int preEnd, int inStart, int inEnd, Map<Integer, Integer> inMap) {
    if (preStart > preEnd || inStart > inEnd) return null;
    TreeNode root = new TreeNode(pre[preStart]);
    int inRoot = inMap.get(root.val);
    int numsLeft = inRoot - inStart;
    root.left = build(pre, preStart + 1, preStart + numsLeft, inStart, inRoot - 1, inMap);
    root.right = build(pre, preStart + numsLeft + 1, preEnd, inRoot + 1, inEnd, inMap);
    return root;
}

private int maxDiameter = 0;
public int diameterOfBinaryTree(TreeNode root) {
    height(root);
    return maxDiameter;
}
private int height(TreeNode node) {
    if (node == null) return 0;
    int left = height(node.left);
    int right = height(node.right);
    maxDiameter = Math.max(maxDiameter, left + right);
    return 1 + Math.max(left, right);
}

public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
    List<List<Integer>> result = new ArrayList<>();
    backtrack(root, targetSum, new ArrayList<>(), result);
    return result;
}
private void backtrack(TreeNode node, int targetSum, List<Integer> path, List<List<Integer>> result) {
    if (node == null) return;
    path.add(node.val);
    if (node.left == null && node.right == null && targetSum == node.val) {
        result.add(new ArrayList<>(path));
    } else {
        backtrack(node.left, targetSum - node.val, path, result);
        backtrack(node.right, targetSum - node.val, path, result);
    }
    path.remove(path.size() - 1); // Backtrack
}

public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
    if (root == null || root == p || root == q) return root;
    TreeNode left = lowestCommonAncestor(root.left, p, q);
    TreeNode right = lowestCommonAncestor(root.right, p, q);
    if (left != null && right != null) return root;
    return left != null ? left : right;
}

public TreeNode deleteNode(TreeNode root, int key) {
    if (root == null) return null;
    if (key < root.val) root.left = deleteNode(root.left, key);
    else if (key > root.val) root.right = deleteNode(root.right, key);
    else {
        if (root.left == null) return root.right;
        if (root.right == null) return root.left;
        TreeNode minNode = findMin(root.right);
        root.val = minNode.val;
        root.right = deleteNode(root.right, root.val);
    }
    return root;
}
private TreeNode findMin(TreeNode node) {
    while (node.left != null) node = node.left;
    return node;
}

// House Robber III
public int rob(TreeNode root) {
    int[] result = robHelper(root);
    return Math.max(result[0], result[1]);
}
private int[] robHelper(TreeNode node) {
    if (node == null) return new int[]{0, 0};
    int[] left = robHelper(node.left);
    int[] right = robHelper(node.right);
    int rob = node.val + left[1] + right[1];
    int notRob = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);
    return new int[]{rob, notRob};
}

public String serialize(TreeNode root) {
    StringBuilder sb = new StringBuilder();
    serializeHelper(root, sb);
    return sb.toString();
}
private void serializeHelper(TreeNode node, StringBuilder sb) {
    if (node == null) { sb.append("X,"); return; }
    sb.append(node.val).append(",");
    serializeHelper(node.left, sb);
    serializeHelper(node.right, sb);
}
public TreeNode deserialize(String data) {
    Queue<String> nodes = new LinkedList<>(Arrays.asList(data.split(",")));
    return deserializeHelper(nodes);
}
private TreeNode deserializeHelper(Queue<String> nodes) {
    String val = nodes.poll();
    if (val.equals("X")) return null;
    TreeNode node = new TreeNode(Integer.parseInt(val));
    node.left = deserializeHelper(nodes);
    node.right = deserializeHelper(nodes);
    return node;
}

private TreeNode prev = null;
public void flatten(TreeNode root) {
    if (root == null) return;
    flatten(root.right);
    flatten(root.left);
    root.right = prev;
    root.left = null;
    prev = root;
}
